# Original operational notes. References establish the relevant domain; checklists are
# 101XVC editorial procedures, not quotations or statements that an agency endorses them.
NOTES = []
def note(folder, title, concept, actions, related, ref):
    NOTES.append(dict(folder=folder, title=title, concept=concept, actions=actions.split(';'), related=related.split('|'), source_ids=ref.split('|')))

# Acquisition and disposition strategy
note('01-Acquisition', 'Acquisition intake', 'An intake record should make the asset, property interest, seller authority, requested economics, and next decision unambiguous.', 'Record county and parcel ID before comparing similarly named addresses;Separate seller statements from verified records;Save contract deadlines and the responsible reviewer;Retain the source and date for each important field', 'Parcel identity|Seller authority|Evidence provenance', 'cfpb_documents|fnma_sales')
note('01-Acquisition', 'Buy box', 'A buy box is an explicit screen for acceptable geography, asset type, price, condition, liquidity, and capital requirements.', 'Document exclusions and exception authority;Keep screening thresholds versioned;Backtest both accepted and rejected leads;Require deeper review when evidence is missing', 'Acquisition intake|Scenario underwriting|Portfolio concentration', 'occ_cre')
note('01-Acquisition', 'Seller authority', 'The party willing to sell must have authority to transfer the offered interest. A mailing name alone does not establish that authority.', 'Match vesting and execution names;Request entity or fiduciary authority documents;Flag estate, trust, bankruptcy, and co-owner issues;Have the settlement professional resolve inconsistencies before committing nonrefundable funds', 'Title review|Contract assignment|Closing checklist', 'cfpb_documents')
note('01-Acquisition', 'Parcel identity', 'A street address is a label; the legal parcel and conveyed property rights determine what is being bought.', 'Keep county parcel IDs as jurisdiction-qualified text;Compare legal description with survey and contract;Identify multiple parcels, condominium units, and excluded acreage;Preserve historic parcel splits and merges', 'GIS joins|Title review|Survey review', 'cfpb_documents|census_api')
note('01-Acquisition', 'Contract assignment', 'Assignment transfers a contractual interest subject to the executed agreement and applicable jurisdictional requirements.', 'Read assignment restrictions and consent requirements;Identify the interest marketed and use written disclosures where required;Track assignee performance and assignor obligations;Ask closing counsel to confirm the transfer and funding sequence', 'Equitable interest disclosure|Double closing|Earnest money', 'trec_interest')
note('01-Acquisition', 'Equitable interest disclosure', 'The marketed interest should be described accurately. Texas rules are a jurisdiction-specific reference rather than a nationwide rule.', 'Verify current state and local requirements before deployment;Disclose contractual rights without implying ownership of the fee interest;Store the actual disclosure and delivery evidence;Review advertisements when the transaction structure changes', 'Contract assignment|Marketing review|State law checklist', 'trec_interest')
note('01-Acquisition', 'Double closing', 'A double closing involves two conveyances. Its viability depends on funding, sequencing, disclosure, title, and the actual contracts.', 'Model both settlements and all closing charges;Confirm permitted use and timing of funds with settlement counsel;Do not assume the second buyer finances the first purchase;Reconcile both final statements after closing', 'Transaction spread|Closing statement reconciliation|Contract assignment', 'cfpb_documents|cfpb_closing')
note('01-Acquisition', 'Novation review', 'A proposed novation requires explicit legal review of which obligations and parties are replaced. A label cannot substitute for executed terms.', 'Describe the intended seller, buyer, listing, and payment relationships;Document consent and release provisions;Review brokerage licensing and marketing authority;Model compensation only from the signed transaction documents', 'Seller authority|State law checklist|Transaction spread', 'trec_interest|cfpb_documents')
note('01-Acquisition', 'Earnest money', 'Earnest money is a transaction deposit whose holder, release conditions, and treatment at closing come from the contract.', 'Record deposit due date and escrow recipient;Track refundable and nonrefundable periods;Treat credited deposits consistently in cash-to-close calculations;Record forfeitures as realized costs rather than successful transactions', 'Closing checklist|Working capital|Contract deadlines', 'cfpb_closing')
note('01-Acquisition', 'Contract deadlines', 'The decision clock is defined by the signed agreement and amendments, not the date a lead enters the CRM.', 'Track inspection, financing, title, deposit, and closing dates separately;Store timezone and business-day convention;Set escalation before expiration;Require executed evidence for deadline extensions', 'Earnest money|Acquisition intake|Exception approval', 'cfpb_documents')
note('01-Acquisition', 'Buyer qualification', 'A disposition buyer is qualified by credible funding, fit with the asset, execution capacity, and the contract terms they accept.', 'Match legal buyer name to proof of funds;Verify financing contingencies and available cash;Record prior completed purchases rather than verbal volume claims;Distinguish a prospective buyer from a closed counterparty', 'Disposition pipeline|Proof of funds|Counterparty risk', 'occ_cre')
note('01-Acquisition', 'Proof of funds', 'Proof of funds is dated evidence of accessible capital. A document generated by the seller is not independent evidence of the buyer\'s liquidity.', 'Record issuer, account owner, currency, and verification route;Redact unnecessary account identifiers in shared copies;Check restrictions and document age;Confirm funds availability through an authorized channel', 'Buyer qualification|Working capital|Evidence provenance', 'occ_cre')
note('01-Acquisition', 'Disposition pipeline', 'A disposition pipeline should separate outreach, indications, contracts, scheduled settlements, and completed closings.', 'Use stages with observable exit criteria;Record failed closings and reasons;Compute conversion from cohorts with equal observation windows;Recognize deal revenue only using the accounting policy and settlement evidence', 'Buyer qualification|Conversion funnel|Closed deal evidence', 'cfpb_closing')
note('01-Acquisition', 'Conversion funnel', 'A conversion funnel uses dated, observable stages to distinguish leads, qualified opportunities, signed contracts, funded closings, and collected revenue.', 'Define denominators and exit evidence for each stage;Measure mature cohorts with consistent observation windows;Retain cancellations and failed closings;Report both unit conversion and net economics after acquisition spending', 'Disposition pipeline|Cash conversion cycle|Realized profit', 'nist_playbook')
note('01-Acquisition', 'Exception approval', 'An exception record makes the accepted risk, approving authority, and expiry visible when a deal falls outside ordinary underwriting.', 'Preserve the original failed rule;Write the compensating evidence and downside;Require named approval and a timestamp;Review recurring exceptions for a policy defect', 'Buy box|Scenario underwriting|Model governance', 'nist_playbook')
note('01-Acquisition', 'Counterparty risk', 'Counterparty risk is the chance that another party cannot or will not perform its contractual obligations.', 'Identify actual contracting entities;Verify funding and operating capacity;Map guarantees and termination rights;Track concentration by counterparty and end purchaser', 'Buyer qualification|Portfolio concentration|Contract deadlines', 'occ_cre|fed_concentration')

# Valuation and core underwriting
note('02-Valuation', 'Net operating income', 'A consistent NOI definition separates property operations from financing, depreciation, corporate overhead, and gains on asset sales.', 'Specify included income and expenses;Reconcile to the operating statement;Normalize one-time items with evidence;Show reserves and capital expenditures separately', 'T12 analysis|Cap rate|Debt service coverage', 'occ_cre|freddie_appraisal')
note('02-Valuation', 'Cap rate', 'Cap rate equals a specified annual NOI divided by value. The income period, stabilization assumption, and expense definition must match the price.', 'Identify trailing or forward NOI;Compare assets with similar risk and rights;Stress NOI and exit cap rate independently;Avoid using a metro average as an exact property valuation', 'Net operating income|Exit value|Comparable sales', 'occ_cre')
note('02-Valuation', 'Exit value', 'For an income property, a simple exit value is exit-year NOI divided by exit cap rate before transaction costs.', 'Apply the cap rate to the correct future year;Subtract selling costs and debt repayment;Test slower lease-up and higher cap rates;Separate gross valuation from equity proceeds', 'Cap rate|Levered cash flow|Scenario underwriting', 'occ_cre|occ_refinance')
note('02-Valuation', 'Comparable sales', 'Comparable selection should reflect similar physical characteristics, property rights, market context, and transaction conditions.', 'Verify that sales actually closed;Record contract and settlement dates when available;Explain why each comparison belongs in the set;Retain rejected candidates and exclusion reasons', 'Comparable adjustments|After repair value|Arm length sale', 'fnma_comps')
note('02-Valuation', 'Comparable adjustments', 'Adjustments estimate market reaction to differences. A construction cost or concession amount need not equal the value adjustment.', 'Use supported paired comparisons when feasible;Avoid mechanical price-per-square-foot corrections;Document time and property-right differences;Show unadjusted and adjusted values together', 'Comparable sales|Sales concessions|Valuation uncertainty', 'fnma_value|fnma_sales')
note('02-Valuation', 'Arm length sale', 'An arm-length comparison is evaluated for normal market exposure and independently motivated participants rather than assumed from a recorded price.', 'Review related parties and unusual concessions;Identify distressed or portfolio transactions;Check deed consideration against available closing evidence;Flag transactions with unclear pricing allocation', 'Comparable sales|Sales concessions|Closed deal evidence', 'fnma_value')
note('02-Valuation', 'Sales concessions', 'Concessions can affect observed sale prices and effective transaction economics.', 'Identify seller credits and financing incentives;Separate ordinary local costs from unusual concessions;Estimate market reaction with evidence;Do not count the same concession in both price adjustment and cash flow', 'Comparable adjustments|Closing statement reconciliation|Transaction spread', 'fnma_value')
note('02-Valuation', 'After repair value', 'ARV is an estimate of market value after a defined completed scope, not the highest nearby listing price.', 'Specify finished condition, size, and legal use;Use verified renovated comparables;Resolve permit and addition assumptions;Produce a range and sensitivity to market changes', 'Comparable sales|Rehab scope|Valuation uncertainty', 'fnma_sales|fnma_comps')
note('02-Valuation', 'Maximum allowable offer', 'A residual offer calculation starts with expected exit proceeds and subtracts repairs, financing, holding, selling costs, risk allowance, and required margin.', 'Use itemized costs instead of an unexplained percentage;Avoid double-counting financing and deposits;Apply downside assumptions before setting a binding offer;Compare the result with actual capital constraints', 'After repair value|Transaction spread|Working capital', 'occ_cre')
note('02-Valuation', 'Transaction spread', 'Transaction spread is the difference between sale or assignment receipts and the specified acquisition and transaction costs. Its definition must be explicit.', 'Define whether the figure is before or after acquisition expenses;Distinguish gross contract spread from 101XVC net income;Include failed-deal costs in portfolio economics;Reconcile the realized result with the closing statement', 'Assignment fee|Realized profit|Closing statement reconciliation', 'cfpb_closing')
note('02-Valuation', 'Assignment fee', 'An assignment fee is transaction compensation under the actual assignment and settlement documents.', 'Store payer, recipient, contractual allocation, and closing condition;Do not equate an underwritten spread with earned fees;Record fee adjustments and settlement deductions;Reconcile earned, billed, and collected balances', 'Contract assignment|Transaction spread|Realized profit', 'trec_interest|cfpb_closing')
note('02-Valuation', 'Realized profit', 'Realized deal profit requires an explicit revenue and cost boundary. Positive sale proceeds alone do not prove profitability.', 'Include acquisition, rehab, holding, financing, and selling costs;State treatment of taxes and overhead;Record cash timing for return calculations;Keep projected, accounting, and realized cash measures separate', 'Accounting gain|IRR|Closed deal evidence', 'irs_disposition')
note('02-Valuation', 'Accounting gain', 'An accounting disposition gain compares recognized proceeds and accounting basis under the reporting entity\'s accounting policy. It is not a full investor cash return.', 'Retain the source\'s measurement label;Keep tax basis and original purchase price distinct;Record entity-share versus asset-level amounts;Do not derive cash IRR from a gain and sale price alone', 'Realized profit|Tax basis|Closed deal evidence', 'irs_basis|irs_disposition')
note('02-Valuation', 'Cash on cash return', 'Cash-on-cash return compares a defined period\'s cash distribution or cash flow with invested cash. Definitions vary, so show both numerator and denominator.', 'Include initial fees and equity-funded capital work;Separate refinancing proceeds from recurring operations;Specify treatment of reserve contributions;Report the period and whether the result is before taxes', 'Levered cash flow|Working capital|IRR', 'occ_cre')
note('02-Valuation', 'IRR', 'IRR is the discount rate at which net present value of a cash-flow sequence is zero. Dates and signs matter; unusual cash flows can create ambiguous results.', 'Use actual dated cash flows for realized returns;Show the equity multiple alongside IRR;Check for multiple sign changes and solver failures;Keep nominal, real, levered, and unlevered cases distinct', 'NPV|Equity multiple|Levered cash flow', 'occ_cre')
note('02-Valuation', 'NPV', 'Net present value discounts each expected cash flow using a chosen rate and subtracts initial investment. The rate is an assumption, not a guaranteed outcome.', 'Document rate and cash-flow timing conventions;Include terminal proceeds and selling expenses;Stress both operating assumptions and discount rate;Compare alternatives using consistent periods', 'IRR|Scenario underwriting|Exit value', 'occ_cre')
note('02-Valuation', 'Equity multiple', 'Equity multiple equals total equity distributions divided by total equity contributions under a stated convention. It ignores how long the investment takes.', 'Include follow-on capital calls;Keep return of capital separate from profit distributions;Exclude hypothetical residual value from realized multiples;Pair the metric with time and IRR', 'IRR|Realized profit|Distribution waterfall', 'occ_cre')
note('02-Valuation', 'Scenario underwriting', 'A useful scenario changes coherent drivers such as price, rents, vacancy, repairs, interest, and duration rather than applying one arbitrary profit haircut.', 'Build downside, base, and upside with explicit assumptions;Show probability assumptions separately;Stress combinations that can occur together;Display cash shortfall and break-even thresholds', 'Sensitivity analysis|Working capital|Exit value', 'occ_cre')
note('02-Valuation', 'Sensitivity analysis', 'Sensitivity isolates how outputs respond to changes in selected assumptions; it does not estimate the probability of those assumptions.', 'Choose drivers tied to uncertain evidence;Show units and base-case position;Test interacting variables when material;Identify the assumptions that change the investment decision', 'Scenario underwriting|Valuation uncertainty|Break even occupancy', 'occ_cre')
note('02-Valuation', 'Valuation uncertainty', 'A valuation range should reflect data quality, comp dispersion, condition uncertainty, market movement, and model performance.', 'Expose missing inspection and pricing evidence;Compare alternative valuation methods;Use observed error bands where validated;Escalate assets outside the model\'s training domain', 'Comparable sales|Model calibration|After repair value', 'fnma_sales|nist')
note('02-Valuation', 'Break even occupancy', 'Break-even occupancy is the occupancy needed for a specified cash-flow or debt-service objective under a stated rent and expense model.', 'Separate fixed and occupancy-dependent expenses;Include concessions and collection loss;State whether reserves and debt service are covered;Test rent declines as well as vacant units', 'Economic occupancy|Debt service coverage|Rent roll', 'occ_cre')
note('02-Valuation', 'Highest and best use review', 'A feasible alternative use must satisfy legal, physical, financial, and market constraints. An attractive rendering does not establish feasibility.', 'Verify zoning and permitted use;Assess utilities, access, and site constraints;Model entitlement time and capital;Compare viable alternatives with a common valuation date', 'Zoning review|Development feasibility|Survey review', 'denver_zoning|occ_cre')

# Finance and capital
note('03-Finance', 'Debt service coverage', 'DSCR equals the lender-defined income or cash-flow measure divided by debt service. Compare ratios only when both definitions match.', 'Use principal and interest required during the period;Identify reserve deductions in the numerator;Stress floating rates and income declines;Treat covenant minimums as contract-specific inputs', 'Net operating income|Debt yield|Loan sizing', 'occ_cre')
note('03-Finance', 'Debt yield', 'Debt yield is a stated annual NOI divided by debt principal. It measures income relative to loan exposure without depending directly on the interest rate.', 'State the NOI definition and loan balance date;Use the same income period across alternatives;Compare with DSCR and LTV rather than replacing them;Stress capital repairs separately', 'Loan to value|Loan sizing|Debt service coverage', 'occ_cre')
note('03-Finance', 'Loan to value', 'LTV compares debt with a defined asset value. A higher valuation can hide unchanged debt risk.', 'Record appraised value, date, and property interest;Separate current value from stabilized value;Include senior and subordinate exposure when evaluating total leverage;Stress value declines and refinance proceeds', 'Debt yield|Refinance risk|Valuation uncertainty', 'occ_cre')
note('03-Finance', 'Loan to cost', 'LTC compares debt with a documented project cost basis. Eligible cost definitions and disbursement mechanics come from loan terms.', 'Break out land, hard costs, soft costs, fees, and reserves;Confirm equity-first or pro-rata funding requirements;Track budget overruns outside the borrowing base;Compare funded balance with committed exposure', 'Construction draws|Development budget|Loan sizing', 'occ_cre')
note('03-Finance', 'Loan sizing', 'Loan proceeds can be constrained simultaneously by value, cost, debt yield, DSCR, liquidity, and lender policy.', 'Calculate each constraint independently;Use the lowest applicable supported result;Include fees and required reserves in usable proceeds;Re-run sizing under refinance and downside assumptions', 'Debt yield|Loan to value|Debt service coverage', 'occ_cre')
note('03-Finance', 'Amortization', 'Amortization is scheduled principal reduction. Loan term and amortization period may differ, creating a balloon balance.', 'Store payment frequency and day-count convention;Separate principal from interest in cash flows;Calculate the balance at maturity;Test the first payment after any interest-only period', 'Balloon maturity|Levered cash flow|Debt service coverage', 'cfpb_closing')
note('03-Finance', 'Balloon maturity', 'A balloon is principal still due when a loan matures. Its repayment depends on cash, a sale, or a new financing transaction.', 'Compute maturity balance from the actual schedule;Set refinance milestones before maturity;Stress lower value and tighter loan sizing;Keep extension rights and fees documented', 'Refinance risk|Amortization|Working capital', 'occ_refinance')
note('03-Finance', 'Floating rate debt', 'Floating-rate debt changes payment or accrued interest with a specified reference rate, spread, reset schedule, and contractual floors.', 'Record the exact rate formula;Model the reset calendar and floor;Include hedge costs and expiration;Stress cash needs before assuming a future refinance', 'Interest rate caps|Debt service coverage|Working capital', 'occ_cre')
note('03-Finance', 'Interest rate caps', 'An interest-rate cap has a notional, strike, reference rate, expiry, premium, and counterparty. It does not eliminate every financing risk.', 'Match hedge terms to the loan;Account for premium funding;Track replacement requirements and expiration;Model uncovered exposure beyond the cap term', 'Floating rate debt|Counterparty risk|Refinance risk', 'occ_cre')
note('03-Finance', 'Refinance risk', 'A maturing loan can fail to refinance even when operations continue, because value, income, rates, liquidity, and lender appetite change.', 'Recalculate debt sizing at maturity;Model required equity paydown;Document extension conditions and contingency liquidity;Track tenant rollover before the refinancing window', 'Balloon maturity|Loan sizing|Portfolio concentration', 'occ_refinance')
note('03-Finance', 'Bridge financing', 'Bridge financing covers a transition such as repair, lease-up, or a future sale. The exit and interim liquidity must be modeled explicitly.', 'Document the business-plan milestone financed;Include origination, exit, and extension fees;Stress a delayed exit;Identify cash needed if permanent financing is smaller than expected', 'Refinance risk|Working capital|Rehab budget', 'occ_cre')
note('03-Finance', 'Working capital', 'Working capital is the cash required to execute before collections arrive. Forecast gross cash uses and receipts rather than relying on a profit total.', 'Use a monthly or weekly cash calendar;Include deposits, payroll, lead costs, repairs, and failed deals;Track committed and available capital separately;Stress closing delays and receivable collection', 'Cash conversion cycle|Bridge financing|Scenario underwriting', 'occ_cre')
note('03-Finance', 'Cash conversion cycle', 'For an acquisition operation, the cash cycle runs from lead spending through contract work and settlement collection. Timing varies by cohort.', 'Track dated cash outflows and receipts;Measure distributions of time to contract and close;Keep cancellation costs in cohort cash flow;Model growth using the peak cash deficit', 'Working capital|Conversion funnel|Realized profit', 'occ_cre')
note('03-Finance', 'Levered cash flow', 'Levered cash flow includes financing receipts, debt service, refinancing, and final debt repayment, with the resulting equity cash flows.', 'Start with unlevered property cash flow;Keep borrowed proceeds out of operating income;Include fees, reserve accounts, and repayment;Reconcile equity cash movements to bank records', 'IRR|Debt service coverage|Realized profit', 'cfpb_closing')
note('03-Finance', 'Distribution waterfall', 'A waterfall allocates available distributions according to the executed agreement. A preferred return and return of capital are different concepts.', 'Model contributions, priority distributions, catch-up, and promote tiers;State simple versus compounded preference;Separate tax distributions and fees;Validate edge cases against the signed agreement', 'Equity multiple|Capital stack|Investor reporting', 'sec_placements')
note('03-Finance', 'Capital stack', 'The capital stack organizes claims such as senior debt, subordinate debt, preferred equity, and common equity by rights and economic priority.', 'Record lien and distribution priorities;Map control and default rights;Model total leverage rather than only senior LTV;Identify personal and entity guarantees', 'Distribution waterfall|Loan to value|Guarantee review', 'occ_cre')
note('03-Finance', 'Guarantee review', 'Guarantees can create payment, completion, environmental, or misconduct-related obligations. The actual signed scope is the relevant evidence.', 'Identify guarantor and covered obligations;Record limits, triggers, survival, and release conditions;Avoid assuming nonrecourse means no contingent obligations;Have counsel reconcile guarantees with the cash model', 'Capital stack|Counterparty risk|Construction draws', 'occ_cre')
note('03-Finance', 'Portfolio concentration', 'Similar geography, tenants, property types, lenders, and counterparties can create correlated downside even across many properties.', 'Aggregate exposure across related entities;Show concentration by capital at risk and expected receipts;Stress a common shock across assets;Set documented limits and exception authority', 'Counterparty risk|Scenario underwriting|Refinance risk', 'fed_concentration')

# Physical and legal due diligence
note('04-Due-Diligence', 'Title review', 'Title review examines the ownership interest and recorded matters affecting transfer or use. A county search does not replace a settlement professional\'s work.', 'Compare vesting, legal description, and contract;Read exceptions, liens, easements, and restrictions;Assign responsibility for curative work;Obtain updated settlement evidence before closing', 'Seller authority|Survey review|Closing checklist', 'cfpb_title')
note('04-Due-Diligence', 'Survey review', 'A survey helps establish boundaries, improvements, access, and possible encroachments for a specified property interest.', 'Confirm survey date and covered parcels;Match the legal description and title exceptions;Review access and utility easements;Resolve discrepancies with surveyor and closing counsel', 'Parcel identity|Title review|Site access', 'cfpb_documents')
note('04-Due-Diligence', 'Site access', 'Physical access and legal access are separate questions. Visible driveway use does not establish a recorded right to use it.', 'Identify access to a public road;Verify easement beneficiary and obligations;Inspect practical emergency and construction access;Check shared-access maintenance responsibilities', 'Survey review|Title review|Development feasibility', 'cfpb_documents|denver_zoning')
note('04-Due-Diligence', 'Zoning review', 'Zoning determines a local regulatory framework for land use and development. Parcel-specific overlays and exceptions matter.', 'Record the governing jurisdiction and code version;Verify permitted use, dimensional standards, and overlays;Review nonconforming use and approval conditions;Obtain written planning confirmation for material assumptions', 'Highest and best use review|Permits|Entitlement schedule', 'denver_zoning')
note('04-Due-Diligence', 'Permits', 'Permits and inspections establish a documented approval process for specific work. A contractor estimate does not prove the work can legally proceed.', 'Check existing and open permits;List approvals required for the proposed scope;Budget review, inspection, and correction time;Retain final inspection and completion evidence', 'Rehab scope|Zoning review|Construction schedule', 'denver_permits')
note('04-Due-Diligence', 'Historic restrictions', 'Historic designation can add review requirements affecting exterior work, materials, demolition, and project timing.', 'Check parcel designation and district boundaries;Determine the required preservation approvals;Align contractor scope with approved work;Include review delay and material costs in the budget', 'Permits|Zoning review|Rehab budget', 'denver_historic')
note('04-Due-Diligence', 'Entitlement schedule', 'Entitlement timing includes review cycles, public processes, required studies, resubmissions, and conditions of approval.', 'Identify each decision-maker and dependency;Separate expected dates from guaranteed dates;Track consultant deliverables and completeness;Stress holding costs if approvals slip', 'Development feasibility|Working capital|Zoning review', 'denver_zoning|denver_permits')
note('04-Due-Diligence', 'Environmental due diligence', 'Environmental due diligence evaluates contamination and related obligations. Qualified professional inquiry and continuing obligations are separate workstreams.', 'Commission the appropriate assessment for the transaction;Track recognized conditions and data gaps;Budget follow-up testing and remediation;Preserve the report, reliance rights, and review date', 'Phase I assessment|Continuing environmental obligations|Environmental red flags', 'epa_aai')
note('04-Due-Diligence', 'Phase I assessment', 'A Phase I environmental assessment is a structured professional investigation; it is not a universal guarantee that a property is uncontaminated.', 'Document scope, timing, and intended reliance;Review historical use and site reconnaissance limitations;Require an environmental professional\'s conclusions;Resolve material findings before relying on the report', 'Environmental due diligence|Environmental red flags|Evidence provenance', 'epa_aai_checklist')
note('04-Due-Diligence', 'Continuing environmental obligations', 'Environmental liability protections can depend on conduct after acquisition as well as pre-acquisition inquiries.', 'Keep obligations in an ongoing asset checklist;Track reasonable steps and institutional controls;Record access cooperation and notices;Have environmental counsel define parcel-specific requirements', 'Environmental due diligence|Asset management|Insurance review', 'epa_liability')
note('04-Due-Diligence', 'Environmental red flags', 'Former industrial use, tanks, unusual odors, stained soils, disposal records, and missing access are prompts for professional investigation rather than diagnoses.', 'Describe observable facts without declaring contamination;Check adjacent historical uses;Escalate incomplete records to the consultant;Hold uncertain cleanup costs as unresolved underwriting inputs', 'Phase I assessment|Rehab contingency|Valuation uncertainty', 'epa_aai')
note('04-Due-Diligence', 'Lead disclosure', 'Lead hazard disclosures and renovation work requirements are distinct. EPA provides federal disclosure guidance for covered housing.', 'Verify applicability from property age and transaction type;Collect required known-hazard information and acknowledgments;Keep delivered records with the signed agreement;Check state and local overlays for the property', 'Lead safe renovation|Seller disclosures|State law checklist', 'epa_lead')
note('04-Due-Diligence', 'Lead safe renovation', 'Renovation of covered older housing can create lead dust exposure and require certified work practices.', 'Identify scope that disturbs painted surfaces;Verify contractor and renovator credentials where required;Budget containment and compliant cleanup;Retain work and disclosure records', 'Lead disclosure|Rehab scope|Contractor selection', 'epa_rrp')
note('04-Due-Diligence', 'Flood review', 'Flood review starts with the actual parcel and applicable effective map. Absence from a mapped high-risk zone does not establish zero flood exposure.', 'Save effective map and retrieval date;Review amendments and elevation information;Obtain an insurance quote using the actual property;Inspect drainage and prior water incidents', 'Insurance review|Natural hazard exposure|GIS joins', 'fema_map')
note('04-Due-Diligence', 'Natural hazard exposure', 'Regional risk indicators are screening inputs. They differ from property-level engineering, insurance underwriting, or a loss forecast.', 'Keep geography and methodology version;Avoid assigning county averages to an exact building;Review relevant hazard-specific evidence;Model deductibles, downtime, and uncovered repair costs', 'Flood review|Insurance review|Data granularity', 'fema_risk')
note('04-Due-Diligence', 'Property condition assessment', 'Condition review translates observed systems, deferred work, and useful lives into immediate repairs and future capital needs.', 'Use a qualified inspector for the scope;Separate urgent deficiencies from planned replacement;Document sampling and access limits;Match the report to scope, reserves, and contractor bids', 'Replacement reserves|Rehab scope|Insurance review', 'freddie_condition')
note('04-Due-Diligence', 'Insurance review', 'Insurance terms affect both recurring expenses and loss exposure. Coverage cannot be inferred solely from premium price.', 'Compare limits, exclusions, deductibles, and valuation basis;Verify occupancy and renovation declarations;Confirm lender requirements and bind date;Stress an uninsured interruption and claim delay', 'Natural hazard exposure|Property condition assessment|Working capital', 'freddie_condition')
note('04-Due-Diligence', 'Seller disclosures', 'Seller disclosures are evidence from a financially interested party. They should be reconciled with inspection, permits, and known records.', 'Use the governing jurisdiction\'s required form;Flag blanks and contradictory answers;Preserve amendments and delivery date;Require independent review for material condition claims', 'Lead disclosure|Property condition assessment|Evidence provenance', 'trec_seller')

# Operating assets and construction
note('05-Operations', 'Rent roll', 'A rent roll is a dated unit or lease inventory. It must be reconciled to signed leases and collected income.', 'Record unit, area, lease term, rent, concessions, and occupancy;Distinguish billed from collected amounts;Reconcile totals with accounting records;Track delinquency and lease rollover separately', 'T12 analysis|Lease audit|Economic occupancy', 'freddie_underwrite')
note('05-Operations', 'T12 analysis', 'Trailing twelve-month analysis shows recent operating performance but may contain one-time items, vacancy changes, and incomplete accounting.', 'Reconcile monthly statements to the annual total;Tag recurring and exceptional items;Verify taxes, insurance, payroll, and utilities;Show historical and normalized NOI separately', 'Net operating income|Rent roll|Expense normalization', 'freddie_appraisal')
note('05-Operations', 'Lease audit', 'Lease audit verifies the legal and economic terms behind a rent roll, including concessions, renewal rights, deposits, and obligations.', 'Sample or review leases according to materiality;Compare terms with tenant ledger;Track amendments and missing signatures;Resolve discrepancies before relying on in-place rent', 'Rent roll|Tenant rollover|Security deposits', 'freddie_underwrite')
note('05-Operations', 'Physical occupancy', 'Physical occupancy counts occupied units or space under an explicit definition. It does not show whether full rent is being collected.', 'Fix the observation date and denominator;Separate offline units from leased vacant units;Track lease-up and move-outs;Compare with economic occupancy and collections', 'Economic occupancy|Rent roll|Break even occupancy', 'census_hvs')
note('05-Operations', 'Economic occupancy', 'Economic occupancy compares actual or earned rental income with a defined gross potential rent measure. Different conventions can produce different ratios.', 'State whether income is billed or collected;Separate concessions and bad debt;Reconcile potential rent to unit inventory;Avoid comparing physical and economic ratios as interchangeable', 'Physical occupancy|Rent concessions|Net operating income', 'freddie_appraisal')
note('05-Operations', 'Rent concessions', 'Concessions reduce effective rent and may occur at move-in, renewal, or throughout a lease term.', 'Record amount, timing, and lease duration;Calculate effective rent consistently;Compare new and renewal leasing separately;Do not omit concessions from a lease-up cash forecast', 'Economic occupancy|Rent roll|Lease up plan', 'freddie_appraisal')
note('05-Operations', 'Tenant rollover', 'Tenant rollover is the calendar of lease expirations and renewal decisions. Concentrated expirations can change income and capital needs.', 'Map lease expiry by month and rent share;Record options and notice dates;Budget vacancy, tenant improvements, and commissions;Stress large-tenant nonrenewal', 'Lease audit|Refinance risk|Portfolio concentration', 'occ_cre')
note('05-Operations', 'Security deposits', 'Tenant deposits create reconciliation and transfer obligations under leases and local law. They are not automatically operating revenue.', 'Reconcile deposit ledger to cash and liabilities;Confirm transfer at acquisition;Keep refunds and deductions documented;Review jurisdiction-specific handling requirements', 'Lease audit|Closing statement reconciliation|State law checklist', 'irs_rental')
note('05-Operations', 'Expense normalization', 'Normalization distinguishes repeatable operating expenses from exceptional items while preserving transparent adjustments.', 'Save the original ledger values;Support each adjustment with evidence;Reassess taxes and insurance for new ownership;Avoid removing a recurring cost merely because it is inconvenient', 'T12 analysis|Net operating income|Property tax underwriting', 'freddie_appraisal')
note('05-Operations', 'Property tax underwriting', 'Property taxes can change after acquisition, reassessment, rate changes, exemptions, or expiring incentives.', 'Verify assessed and taxable values independently;Use the actual local taxing entities;Model a reassessment scenario;Do not assume the seller\'s tax bill continues indefinitely', 'Expense normalization|Assessor versus collector|Scenario underwriting', 'irs_rental')
note('05-Operations', 'Replacement reserves', 'Replacement reserves fund future capital items and should reflect condition, useful life, financing terms, and the business plan.', 'Use a system-level replacement schedule;Separate deposit contributions from actual capital spending;Track reserve restrictions and withdrawals;Avoid treating required lender deposits as free operating cash', 'Property condition assessment|Net operating income|Working capital', 'fnma_reserves')
note('05-Operations', 'Rehab scope', 'A rehab scope specifies the work, quantities, standard, exclusions, permits, and acceptance criteria before a reliable budget can be set.', 'Use room and system-level line items;Tie finish quality to the target comps;Identify concealed-condition assumptions;Have the contractor acknowledge exclusions and dependencies', 'After repair value|Rehab budget|Permits', 'freddie_condition')
note('05-Operations', 'Rehab budget', 'A complete rehab budget includes hard costs, professional fees, approvals, contingency, financing, and carry through completion.', 'Compare bids on identical quantities and scope;Separate allowances from fixed prices;Track committed, paid, and forecast-to-complete cost;Update the exit model after every material change', 'Rehab scope|Rehab contingency|Construction draws', 'occ_cre')
note('05-Operations', 'Rehab contingency', 'Contingency is reserved capacity for defined uncertainty. It should not mask known work omitted from the estimate.', 'List risks that the contingency covers;Separate owner changes from hidden conditions;Keep approval and remaining reserve visible;Stress overruns beyond the allowance', 'Rehab budget|Change orders|Property condition assessment', 'occ_cre')
note('05-Operations', 'Contractor selection', 'Contractor selection weighs relevant capacity, credentials, insurance, scope understanding, references, and payment terms.', 'Verify licensing and credentials through official channels;Ask for similar completed projects;Review subcontracting and lien-release processes;Require a written scope and acceptance criteria', 'Lead safe renovation|Change orders|Rehab scope', 'epa_rrp|denver_permits')
note('05-Operations', 'Construction draws', 'A draw is a financing disbursement tied to eligible completed work and loan documentation.', 'Reconcile invoices, inspections, and approved budget;Verify lien waivers with the settlement or lender process;Track retainage and remaining commitment;Do not treat an approved budget as cash already available', 'Loan to cost|Rehab budget|Working capital', 'occ_cre')
note('05-Operations', 'Change orders', 'A change order records a scope, cost, or schedule change and who authorized it.', 'Require written pricing and reason before work where feasible;Link the change to the original line item;Update completion forecast and contingency;Keep cumulative changes visible to the investment reviewer', 'Rehab contingency|Construction schedule|Exception approval', 'occ_cre')
note('05-Operations', 'Construction schedule', 'A schedule should model dependencies, approvals, lead times, inspections, and critical work rather than a single estimated finish date.', 'Track baseline and current forecast;Flag critical-path delays;Link schedule movement to carry costs;Retain evidence of milestone completion', 'Entitlement schedule|Change orders|Working capital', 'denver_permits|occ_cre')
note('05-Operations', 'Lease up plan', 'A lease-up forecast links delivery, marketing, applications, signed leases, move-ins, effective rent, and collection timing.', 'Model unit availability by month;Use supported rent and absorption assumptions;Include concessions and marketing spend;Stress a slower pace while fixed costs continue', 'Rent concessions|Economic occupancy|Development feasibility', 'occ_cre')
note('05-Operations', 'Development feasibility', 'Development feasibility combines entitlement, site conditions, construction, financing, absorption, and exit economics.', 'Map legal and physical constraints;Price the complete development budget;Model delayed stabilization and refinance;Require updated evidence at each capital commitment', 'Highest and best use review|Entitlement schedule|Development budget', 'occ_cre')
note('05-Operations', 'Development budget', 'A development budget should reconcile land, site work, building costs, tenant work, consultants, permits, fees, interest, and reserves.', 'Identify who bears each cost;Store estimate date and scope basis;Separate committed and conceptual costs;Reconcile total cost with loan-to-cost and equity requirements', 'Loan to cost|Development feasibility|Construction draws', 'occ_cre')
note('05-Operations', 'Asset management', 'Asset management checks whether actual operations, capital work, financing, and disposition remain consistent with the approved business plan.', 'Review budget versus actual monthly;Track unresolved physical and legal obligations;Update lease rollover and debt calendar;Document decisions and resulting cash impact', 'T12 analysis|Continuing environmental obligations|Investor reporting', 'freddie_underwrite')
note('05-Operations', 'Energy benchmarking', 'Energy benchmarking compares measured consumption under defined building-use and weather assumptions.', 'Reconcile meters and whole-building coverage;Store floor area, occupancy, and usage definitions;Evaluate savings against installed cost;Treat self-reported peer data as imperfect comparisons', 'Operating efficiency|Data provenance|Expense normalization', 'energy|energy_sample')
note('05-Operations', 'Operating efficiency', 'Operating efficiency improvements should be measured against a stable baseline while checking service quality and deferred-maintenance effects.', 'Define the expense and output being improved;Normalize for occupancy and weather where relevant;Track implementation and maintenance costs;Avoid counting cost shifting as true savings', 'Energy benchmarking|Net operating income|Asset management', 'energy')
note('05-Operations', 'Closing checklist', 'Closing readiness means contractual, title, financing, physical, authority, and settlement requirements are resolved or explicitly accepted.', 'Review the complete settlement packet;Verify final funds and instructions independently;Complete the agreed walkthrough;Store signed documents and recorded conveyance evidence', 'Closing statement reconciliation|Title review|Closed deal evidence', 'cfpb_documents|cfpb_walkthrough')
note('05-Operations', 'Closing statement reconciliation', 'Closing reconciliation turns projected economics into a documented transaction result and distinguishes credits from cash movements.', 'Match buyer and seller names to the agreement;Reconcile sale proceeds, deposits, prorations, fees, and debt payoff;Compare actual cash with bank records;Explain every material deviation from underwriting', 'Realized profit|Earnest money|Accounting gain', 'cfpb_closing')

# Markets and public records
note('06-Markets', 'Market boundary', 'A useful market boundary follows substitutable demand and property characteristics rather than an arbitrary postal radius.', 'State the target tenant or purchaser;Compare competing submarkets and legal use;Save geography IDs and boundary versions;Review whether the boundary changes comp selection', 'Comparable sales|Data granularity|Demand drivers', 'fnma_comps')
note('06-Markets', 'Demand drivers', 'Demand analysis links households, jobs, income, access, and competing housing options with the product being offered.', 'Use geography-appropriate statistics;Distinguish correlation from causal evidence;Compare income and rent burdens;Stress a local employer or sector shock', 'ACS interpretation|Market boundary|Portfolio concentration', 'census_acs')
note('06-Markets', 'ACS interpretation', 'ACS estimates carry sampling uncertainty and cover a defined period. A five-year estimate is not a snapshot of the final year alone.', 'Save dataset vintage and variable definitions;Retrieve estimates with margins of error;Compare like periods and geographies;Do not overinterpret small differences or thin populations', 'Margins of error|Data vintage|Census API', 'census_api')
note('06-Markets', 'Margins of error', 'Survey margins of error communicate uncertainty in estimates. They belong beside the estimate in downstream tables.', 'Preserve estimate and uncertainty fields;Flag suppressed and annotated values;Check whether comparisons are statistically meaningful;Avoid treating a county survey number as a precise parcel fact', 'ACS interpretation|Data granularity|Valuation uncertainty', 'census_api')
note('06-Markets', 'Building permits data', 'Building permits measure authorizations for covered construction. They are different from starts, completions, deliveries, and available inventory.', 'Keep units separate from building counts;Record survey geography and reporting vintage;Compare authorizations with starts and completions;Do not assume every permitted unit will be delivered on time', 'Housing starts and completions|Supply pipeline|Data vintage', 'census_bps')
note('06-Markets', 'Housing starts and completions', 'Construction surveys distinguish beginning a project from completing units, and are generally not an exact parcel inventory.', 'Check coverage and regional granularity;Separate single-family and multifamily units;Use revisions consistently;Compare completions with local absorption evidence', 'Building permits data|Supply pipeline|Lease up plan', 'census_soc')
note('06-Markets', 'Supply pipeline', 'A supply pipeline should separate proposed, entitled, permitted, under-construction, delivered, and leased units.', 'Assign each project an evidence-based stage;Avoid summing overlapping datasets;Track expected delivery and delays;Compare competitive supply with the actual product segment', 'Building permits data|Housing starts and completions|Market boundary', 'census_bps|census_soc')
note('06-Markets', 'Vacancy statistics', 'Vacancy estimates depend on survey population, geography, period, and definitions. Different Census surveys should not be mixed casually.', 'State the survey and vacancy definition;Keep rental and homeowner vacancy distinct;Review uncertainty and comparability;Use property-level rent rolls for the subject asset', 'Physical occupancy|Data granularity|ACS interpretation', 'census_vacancy')
note('06-Markets', 'House price indexes', 'A house-price index measures change for a specified dataset and methodology. It is not an appraisal of every home in that geography.', 'Retain index type and base period;Separate seasonally adjusted and unadjusted series;Keep release and observation dates;Use the index as market context rather than an exact ARV', 'Repeat sales methodology|Data vintage|After repair value', 'fhfa_hpi')
note('06-Markets', 'Repeat sales methodology', 'Repeat-sales indexes use repeat observations to estimate price changes while applying a specified sample and statistical method.', 'Read coverage and exclusions;Check how geography and property mix affect representativeness;Do not apply national change blindly to a local niche;Document any time adjustment derived from the series', 'House price indexes|Comparable adjustments|Valuation uncertainty', 'fhfa_method')
note('06-Markets', 'Assessor versus collector', 'Assessment records and tax-collection records answer different questions. A assessed value is not a payoff balance or evidence that taxes are current.', 'Identify each custodial office;Preserve assessment year and tax period;Reconcile parcel identity across systems;Request a dated payoff or collection status when needed', 'Property tax underwriting|Delinquent tax records|Public records request', 'foia|irs_rental')
note('06-Markets', 'Delinquent tax records', 'A delinquency record is dated evidence about a tax account. Status can change through payment, appeal, transfer, installment plan, or correction.', 'Store tax year and record-as-of date;Preserve raw account and parcel fields;Verify current status before acting;Keep charges, penalties, and total balance separate', 'Assessor versus collector|Data freshness|Parcel identity', 'foia')
note('06-Markets', 'Public records request', 'A targeted request describes existing records, custodians, date range, fields, and preferred format. Federal FOIA does not govern every local office.', 'Check the applicable state or local public-records law;Search existing downloads before requesting;Use a narrow machine-readable request;Track fees, response, exemptions, and appeal options', 'FOIA scope|County source registry|Evidence provenance', 'foia|foia_faq')
note('06-Markets', 'FOIA scope', 'Federal FOIA is a process for federal agency records. County tax rolls typically require the relevant state or local process.', 'Identify the actual records custodian;Do not demand creation of a new analysis under a records request;Keep requested records and requested explanations separate;Record the governing law and response status', 'Public records request|Assessor versus collector|State law checklist', 'foia_faq')
note('06-Markets', 'County source registry', 'A county registry should identify the authoritative assessor, collector, recorder, GIS, courts, and downloadable record sources separately.', 'Store jurisdiction-qualified agency names;Record source format, update cadence, and access terms;Test downloads and record actual status;Keep unsupported and manual sources visible', 'Public records request|Data freshness|Responsible crawling', 'foia|robots')

# Legal and tax checkpoints, intentionally not purported nationwide legal advice
note('07-Legal-Tax', 'State law checklist', 'A state law checklist is a review record for a specific jurisdiction, transaction structure, and effective date.', 'Identify governing licensing, disclosure, brokerage, contract, and records rules;Record counsel review and actual sources;Track changes and effective dates;Avoid applying one state\'s rule to another', 'Equitable interest disclosure|Novation review|Public records request', 'trec_interest')
note('07-Legal-Tax', 'Tax basis', 'Tax basis is an investment measure used for tax purposes and can change through adjustments. It is different from current market value.', 'Record acquisition allocation and supporting settlement records;Track capital improvements and basis adjustments;Keep book and tax schedules separate;Have the accountant resolve treatment before filing', 'Depreciation review|Accounting gain|Realized profit', 'irs_basis')
note('07-Legal-Tax', 'Depreciation review', 'Depreciation depends on asset classification, placed-in-service facts, tax rules, and elections. Land and building allocations should be supported.', 'Retain purchase and improvement allocations;Record placed-in-service dates;Separate repairs from capitalized improvements;Use the current tax-year guidance with the accountant', 'Tax basis|Rental income records|Expense classification', 'irs_rental')
note('07-Legal-Tax', 'Rental income records', 'Rental reporting requires accurate records of receipts, deposits, expenses, and property use under the applicable tax framework.', 'Keep bank receipts and tenant ledgers reconcilable;Separate refundable deposits from earned rent;Identify personal-use or vacation-home facts;Retain invoices and records for the tax professional', 'Security deposits|Depreciation review|T12 analysis', 'irs_rental')
note('07-Legal-Tax', 'Expense classification', 'An operating, capital, financing, or acquisition label should reflect the applicable accounting and tax policy rather than the desired NOI.', 'Document repair and improvement facts;Preserve invoices and scope;Keep financing fees separate from property operations;Reconcile management reporting with accountant classifications', 'Expense normalization|Tax basis|Net operating income', 'irs_rental|irs_basis')
note('07-Legal-Tax', 'Disposition tax review', 'Tax consequences of a sale depend on basis, use, holding facts, character, recapture, and applicable rules.', 'Compile sale proceeds and transaction expenses;Reconcile basis schedules;Separate tax estimates from pre-tax investment returns;Have the tax professional review before reporting final after-tax outcomes', 'Tax basis|Accounting gain|Closing statement reconciliation', 'irs_disposition')
note('07-Legal-Tax', 'Exchange planning', 'A proposed exchange requires transaction-specific tax planning and timing controls. A profitable sale does not automatically qualify for deferral.', 'Document asset use and transaction structure;Obtain professional review before proceeds are received;Track statutory and contractual deadlines from authoritative guidance;Model liquidity and failed-exchange alternatives', 'Disposition tax review|Working capital|Contract deadlines', 'irs_disposition')
note('07-Legal-Tax', 'Fair housing review', 'Housing-related decisions and communications should be reviewed against applicable fair housing obligations and documented business criteria.', 'Use objective property and financial criteria;Review screening and marketing features for improper protected-class use;Keep decision explanations and correction channels;Verify current federal, state, and local requirements', 'Marketing review|Model governance|Feature selection', 'hud_fair')
note('07-Legal-Tax', 'Marketing review', 'Marketing claims should match the interest offered, actual authority, source evidence, and applicable advertising requirements.', 'Verify ownership or contractual-interest wording;Keep modeled returns labeled as projections;Review property and investment claims separately;Store the approved version and supporting evidence', 'Equitable interest disclosure|General solicitation|Fair housing review', 'trec_interest|sec_solicitation')
note('07-Legal-Tax', 'General solicitation', 'Offering rules affect how an issuer may contact prospective securities investors. The chosen exemption and actual conduct must be reviewed together.', 'Record the selected pathway and counsel\'s requirements;Review outbound campaign and public materials before launch;Keep relationship and verification evidence;Do not assume an investor directory grants solicitation permission', 'Investor eligibility|Capital raising review|Marketing review', 'sec_solicitation')
note('07-Legal-Tax', 'Investor eligibility', 'Private offering eligibility and verification depend on the applicable exemption and investor circumstances.', 'Use current authoritative criteria;Retain appropriate verification evidence securely;Separate interested prospects from admitted investors;Reconcile subscriptions with the offering documents', 'General solicitation|Capital raising review|Investor reporting', 'sec_placements')
note('07-Legal-Tax', 'Capital raising review', 'Raising capital involves selecting a lawful offering pathway and maintaining accurate terms, records, filings, and disclosures.', 'Document issuer, security, use of proceeds, and exemption;Obtain review of financial claims and risk factors;Track required filings and state obligations;Keep signed subscription and cap-table records consistent', 'Investor eligibility|General solicitation|Distribution waterfall', 'sec_offerings')
note('07-Legal-Tax', 'Investor reporting', 'Investor reporting distinguishes actual operating performance, cash distributions, accounting results, and forecasts.', 'Reconcile reported numbers to the ledger;Explain assumptions and material variances;Disclose related-party fees and transaction boundaries;Keep versions and delivery records', 'Realized profit|Distribution waterfall|Accounting gain', 'sec_placements')
note('07-Legal-Tax', 'Email outreach controls', 'Commercial email operations need truthful presentation, appropriate sender information, and a reliable suppression process under applicable law.', 'Review sender and subject accuracy;Maintain opt-out processing and suppression records;Keep list provenance and campaign versions;Verify additional securities-marketing requirements for investor outreach', 'General solicitation|Contact provenance|Marketing review', 'ftc_email')
note('07-Legal-Tax', 'Telephone outreach controls', 'Telephone outreach requirements depend on the actual campaign, calling method, recipients, and jurisdiction.', 'Review federal and state requirements with counsel;Keep consent and suppression records;Use a documented calling-time policy;Do not infer permission from a public phone listing', 'Contact provenance|Email outreach controls|State law checklist', 'ftc_calls')

# Independent data / classical ML / NLP
note('08-Data-ML', 'Evidence provenance', 'Provenance records where a claim came from, when it was observed, what changed it, and who accepted it.', 'Store source URL, date, checksum, and locator;Link transformed fields to raw inputs;Distinguish source facts from analyst inference;Retain contradictory evidence and resolution', 'Data provenance|Closed deal evidence|Evidence status', 'nist')
note('08-Data-ML', 'Data provenance', 'Data provenance follows records across acquisition, cleaning, joining, modeling, and output generation.', 'Record source licenses and access conditions;Version datasets and transformations;Preserve stable row IDs;Attach lineage to exported results', 'Evidence provenance|Data versioning|Data quality checks', 'nist_playbook')
note('08-Data-ML', 'Evidence status', 'An evidence status distinguishes observed source facts, self-reported claims, verified settlement records, unresolved claims, and analyst estimates.', 'Use an explicit allowed-status vocabulary;Require evidence to upgrade a status;Keep status separate from model confidence;Do not let attractive economics override missing evidence', 'Closed deal evidence|Evidence provenance|Model calibration', 'nist')
note('08-Data-ML', 'Closed deal evidence', 'A closed-deal record needs explicit completion evidence and a precise profit measure. An asking price, signed contract, or sales volume is insufficient.', 'Record actual asset and seller interest;Keep reported closing period if the exact date is unavailable;Separate gross price, net proceeds, basis, gain, and cash return;Require complete dated cash flows before computing realized IRR', 'Accounting gain|Realized profit|Evidence status', 'irs_disposition|cfpb_closing')
note('08-Data-ML', 'Data freshness', 'Freshness is measured from the relevant observation or effective date, not merely when a scraper downloaded the page.', 'Store publication, effective, and retrieval dates separately;Set field-specific expiry rules;Detect stale unchanged files;Show age in decision views', 'Data vintage|County source registry|Responsible crawling', 'census_api')
note('08-Data-ML', 'Data vintage', 'A vintage identifies the dataset release and revision state available at a particular time.', 'Keep release date and observation period;Avoid silently mixing revised and unrevised series;Preserve the vintage used for historical decisions;Recompute outputs deliberately after updates', 'House price indexes|ACS interpretation|Temporal validation', 'fhfa_hpi|census_api')
note('08-Data-ML', 'Data granularity', 'Granularity describes the smallest supported unit and period of measurement. A model cannot create factual resolution absent from the source.', 'Keep parcel, tract, county, metro, and state levels distinct;Document aggregation and allocation assumptions;Avoid assigning survey facts to named individuals;Flag mismatched geography in joins', 'Margins of error|GIS joins|Natural hazard exposure', 'census_acs')
note('08-Data-ML', 'Census API', 'Census API queries should retain dataset year, variable names, geography predicates, annotations, and the exact request.', 'Inspect the dataset variable dictionary;Keep leading zeros in FIPS fields;Retrieve uncertainty and annotation variables where relevant;Cache responses and record retrieval failures explicitly', 'ACS interpretation|GIS joins|Data provenance', 'census_api')
note('08-Data-ML', 'GIS joins', 'Spatial joins attach records through a defined coordinate system and geometry relationship. They are not inherently more reliable than the geometry.', 'Record coordinate reference systems;Check geocoding confidence;Validate points near jurisdiction boundaries;Keep address and parcel-identifier joins as independent checks', 'Parcel identity|Data granularity|County source registry', 'census_api')
note('08-Data-ML', 'Entity resolution', 'Entity resolution identifies when differently formatted records refer to the same property, company, or person.', 'Normalize for comparison while preserving originals;Use jurisdiction and parcel keys for property matches;Assign confidence and review ambiguous candidates;Avoid merging common names without independent evidence', 'Parcel identity|Contact provenance|Data quality checks', 'nist_playbook')
note('08-Data-ML', 'Contact provenance', 'A contact record should indicate whether a phone or email was publicly listed, provided directly, verified, inferred, or outdated.', 'Save the public source and observation date;Do not present inferred addresses as verified;Track suppression and update history;Use business context and applicable outreach rules', 'Entity resolution|Email outreach controls|Telephone outreach controls', 'ftc_email|ftc_calls')
note('08-Data-ML', 'Responsible crawling', 'A crawler is a repeatable data-acquisition process with site-specific access policy, robots handling, rate limits, caching, and visible failures.', 'Use an identifiable user agent;Respect allowed paths and response backoff;Avoid bypassing authentication or access restrictions;Record blocked and unsupported sources without fabricating results', 'Robots policy|SEC source harvesting|Data provenance', 'robots')
note('08-Data-ML', 'Robots policy', 'Robots directives describe crawler access preferences under the Robots Exclusion Protocol. Site terms and legal access rights require separate review.', 'Fetch and cache robots.txt for the actual origin;Apply user-agent-specific rules;Re-check redirected destinations;Treat unavailable policy conservatively in the included harvester', 'Responsible crawling|Source caching|SEC source harvesting', 'robots')
note('08-Data-ML', 'SEC source harvesting', 'SEC permits scripted access subject to its published fair-access requirements. An operational harvester should use a genuine contact-bearing user agent and conservative rate.', 'Record canonical filing and section URLs;Stay below published limits and respect errors;Cache retrieved records and hashes;Prefer small XBRL note tables for targeted extraction', 'Responsible crawling|Closed deal evidence|Source caching', 'sec_access')
note('08-Data-ML', 'Source caching', 'Caching separates evidence retrieval from analysis and reduces repeated traffic. Cache existence alone does not establish source freshness.', 'Store original URL, retrieval time, response type, and SHA-256;Verify changed content before replacing prior evidence;Keep failed requests distinguishable from empty documents;Restrict redistribution according to rights and license', 'Data freshness|Evidence provenance|Responsible crawling', 'robots|sec_access')
note('08-Data-ML', 'Classical NLP', 'Classical NLP can retrieve, classify, and extract from text with tokenization, word statistics, rules, and supervised models without hosted language-model services.', 'Choose a narrow measurable task;Keep labeled examples and evaluation cases;Return source evidence with extracted values;Record low confidence and unsupported input', 'TF IDF retrieval|Rule based extraction|Model validation', 'sklearn_text')
note('08-Data-ML', 'TF IDF retrieval', 'TF-IDF represents text by weighted token frequencies. Similarity retrieves documents sharing useful terms; it does not establish that a financial claim is true.', 'Use consistent tokenization for corpus and query;Keep document IDs and source metadata;Evaluate real information needs and synonym failures;Show matched passages with provenance', 'Classical NLP|Search evaluation|Rule based extraction', 'sklearn_tfidf')
note('08-Data-ML', 'Rule based extraction', 'Rules can extract predictable amounts, dates, entities, and document fields while preserving the supporting span.', 'Scope patterns to known document formats;Keep unit and currency context;Validate nearby headings and table labels;Send ambiguous or changed layouts to review', 'Classical NLP|Evidence provenance|Extraction quality', 'sklearn_text')
note('08-Data-ML', 'Extraction quality', 'Extraction quality measures whether fields and evidence spans match the source, including units, signs, date precision, and entity scope.', 'Use reviewed representative examples;Measure precision and missing-field rate;Test negative values and table-scale conversions;Reject layout changes that invalidate assumptions', 'Rule based extraction|Closed deal evidence|Data quality checks', 'nist_playbook')
note('08-Data-ML', 'Feature selection', 'Features should be available at the decision time, relevant to the task, legally usable, and supported by the source.', 'Define each feature and availability timestamp;Remove target leakage and unsupported precision;Review protected-class and proxy use;Document missing-value treatment', 'Fair housing review|Temporal validation|Model governance', 'nist')
note('08-Data-ML', 'Temporal validation', 'Temporal validation evaluates predictions on later observations using only information available before the prediction time.', 'Split by date before fitting transformations;Keep the same property out of conflicting evaluation groups;Retain dataset vintages;Compare performance across market regimes', 'Data vintage|Feature selection|Model validation', 'nist_playbook')
note('08-Data-ML', 'Model validation', 'Validation asks whether a model works for its intended use with representative data, clear metrics, and known failure boundaries.', 'Compare with a simple baseline;Use held-out examples and stress cases;Review performance by geography and property type;Document when manual review overrides predictions', 'Model calibration|Model governance|Temporal validation', 'nist')
note('08-Data-ML', 'Model calibration', 'Calibration compares predicted confidence or outcome distributions with observed results. A high similarity score is not automatically a probability.', 'Define the event being predicted;Use held-out observed outcomes;Display reliability and error by segment;Keep sparse segments and uncertainty visible', 'Valuation uncertainty|Model validation|Evidence status', 'nist_playbook')
note('08-Data-ML', 'Model governance', 'Model governance assigns ownership, scope, version, validation, deployment rules, monitoring, and retirement criteria.', 'Maintain model cards and approved use cases;Record training data and configuration hashes;Separate material approval from routine operation;Provide a rules-based fallback and rollback procedure', 'Model validation|Offline operation|Exception approval', 'nist')
note('08-Data-ML', 'Search evaluation', 'Search evaluation tests whether retrieval returns relevant evidence for actual user questions, including failure and no-answer cases.', 'Create reviewed question-document pairs;Measure top-k relevance and source coverage;Test synonyms, numeric facts, and conflicting evidence;Evaluate abstention when the corpus lacks support', 'TF IDF retrieval|Evidence provenance|Offline operation', 'sklearn_text')
note('08-Data-ML', 'Data quality checks', 'Data-quality checks protect joins and calculations by detecting missing identifiers, duplicate records, impossible values, unit mismatches, and stale observations.', 'Specify field contracts and valid ranges;Keep rejected rows with reasons;Compare aggregate totals before and after transformations;Treat null as unknown rather than zero', 'Entity resolution|Data provenance|Extraction quality', 'nist_playbook')
note('08-Data-ML', 'Data versioning', 'Versioning binds a result to the exact records, code, configuration, and assumptions that produced it.', 'Hash input and output files;Use stable semantic schemas;Record migration and transformation versions;Make prior analytical runs reproducible', 'Data provenance|Source caching|Model governance', 'nist_playbook')
note('08-Data-ML', 'Offline operation', 'Offline operation means the deployed analysis and search use local code, stored records, and local model parameters after installation.', 'Distinguish acquisition connectivity from inference independence;Test with network access disabled;Keep dependency and dataset versions;Show when locally cached evidence is stale', 'Classical NLP|Model governance|Data freshness', 'sklearn_text|nist_playbook')

# Twelve-component XVCbrain underwriting framework. User requirements are preserved
# verbatim in docs/UNDERWRITING-REQUIREMENTS.md; these are original operational notes.
source('survival_competing', 'Analysis of Competing Risks', 'https://scikit-survival.readthedocs.io/en/stable/user_guide/competing-risks.html', 'scikit-survival')
source('sklearn_calibration', 'Probability Calibration', 'https://scikit-learn.org/stable/modules/calibration.html', 'scikit-learn')
source('mlflow_registry', 'ML Model Registry', 'https://mlflow.org/docs/latest/ml/model-registry/', 'MLflow')
source('sklearn_leakage', 'Common Pitfalls and Recommended Practices', 'https://scikit-learn.org/stable/common_pitfalls.html', 'scikit-learn')
note('11-Underwriting-Intelligence', 'Permanent transaction identity', 'An asset identity and a transaction episode are separate records. A property can be offered, refused, recontracted, and sold across multiple distinct episodes.', 'Link canonical parcel and property IDs to each episode;Preserve source-specific CRM IDs and owner entities;Store conflicting fields with evidence;Prevent duplicate episodes from inflating outcome counts', 'Parcel identity|Entity resolution|Learning decision ledger', 'nist_playbook')
note('11-Underwriting-Intelligence', 'Underwriting evidence acquisition', 'Public records enrich property context; internal offers, bids, milestones, expenses, and settlements establish how the acquisition operation actually performs.', 'Record observed and available-at timestamps separately;Attach raw evidence or source spans to material fields;Track collector failures and stale records;Require settlement evidence before labeling realized economics', 'Evidence provenance|Temporal evidence availability|Settled economics reconciliation', 'nist_playbook')
note('11-Underwriting-Intelligence', 'Local value and repair model', 'As-is value, ARV, executable investor price, and repair cost are distinct prediction targets. A new county needs explicit uncertainty until local errors are measured.', 'Train value estimates on verified comparable transactions;Train repairs on itemized scopes and actual costs;Keep regional pooling and local adjustments explicit;Evaluate later observations by geography and condition', 'After repair value|Rehab scope|Temporal validation', 'fnma_sales|nist_playbook')
note('11-Underwriting-Intelligence', 'Offer negotiation optimization', 'Offer scenarios combine acquisition price, terms, expected receipts, execution probability, loss exposure, cash timing, and capacity constraints.', 'Separate supplied scenario assumptions from validated estimates;Rank opening, target, counteroffer, and ceiling alternatives by the stated objective;Show losses and cash shortfalls;Abstain from probability-weighted recommendations when essential estimates lack evidence', 'Counterfactual seller acceptance|Transaction portfolio economics|Capacity aware acquisition', 'occ_cre|nist_playbook')
note('11-Underwriting-Intelligence', 'Seller response evidence', 'Recorded offers, counteroffers, refusals, response intervals, and unresolved objections can support response modeling after decision-time information is reconstructed.', 'Keep refused and unanswered offers;Extract asks and deadlines with supporting text spans;Identify which observations were available before each offer;Test follow-up strategies with controlled comparisons', 'Counterfactual seller acceptance|Rule based extraction|Learning decision ledger', 'nist_playbook|sklearn_leakage')
note('11-Underwriting-Intelligence', 'Buyer partner liquidity', 'An executable bid has price, terms, funds, timing, conditions, and expiry. Stated interest is a weaker evidence category.', 'Track bids and capacity with observation dates;Record partner approvals, rejections, pricing feedback, and settlements;Expose limited buyer visibility;Account for multiple properties competing for the same capacity', 'Buyer qualification|Capacity aware acquisition|Demand deterioration detection', 'occ_cre')
note('11-Underwriting-Intelligence', 'Competing closing outcomes', 'Closing, cancellation, and expiration can be mutually exclusive terminal outcomes for an episode. Cause-specific cumulative incidence preserves that competition.', 'Define outcome causes and episode boundaries consistently;Keep unfinished episodes right-censored;Estimate closing probability by each horizon with risk-set support;Do not treat cancellations as ordinary censoring when estimating actual closing incidence', 'Right censoring|Time origin and landmark forecasts|Cash receipt lag', 'survival_competing')
note('11-Underwriting-Intelligence', 'Intervention queue', 'A work queue can prioritize unresolved evidence and deadline exposure. Ranking a task does not establish the causal financial benefit of performing it.', 'Identify document, access, inspection, bid, and partner-review blockers;State why the forecast depends on each blocker;Separate heuristic urgency from estimated treatment effect;Record completion and subsequent outcomes without claiming causation', 'Value of information|Learning decision ledger|Versioned transaction rules', 'nist_playbook')
note('11-Underwriting-Intelligence', 'Versioned transaction rules', 'Rules determine permitted actions and contractual requirements; models estimate outcomes. Statistical output cannot override an applicable rule or unreviewed exception.', 'Select rules by jurisdiction, counterparty, contract, and effective date;Store review status and source;Preserve approvals and exceptions;Keep assumption defaults distinct from reviewed legal or partner requirements', 'State law checklist|Exception approval|Model governance', 'nist_playbook')
note('11-Underwriting-Intelligence', 'Transaction portfolio economics', 'Gross spread, partner share, retained fee, attributable costs, collections, funding needs, and loss exposure require separate fields and explicit timing.', 'Reconcile actual receipts with settlement and bank records;Model slower cash receipt and failed transactions;Aggregate market and partner concentration;Apply marginal allocation only after its incremental contribution assumptions are supported', 'Cash receipt lag|Settled economics reconciliation|Marginal marketing allocation', 'occ_cre|cfpb_closing')
note('11-Underwriting-Intelligence', 'Learning decision ledger', 'A learning ledger preserves evidence available, prediction, recommendation, actual action, outcome, and settled economics as linked records.', 'Make original decision snapshots immutable;Record model, rules, features, and assumption versions;Append corrections and outcomes instead of rewriting history;Keep refusals, losses, and open episodes alongside wins', 'Temporal evidence availability|Model promotion gate|Settled economics reconciliation', 'nist_playbook|mlflow_registry')
note('11-Underwriting-Intelligence', 'Independent underwriting platform', 'Independent underwriting performs local computation using owned records and local model artifacts. New source acquisition can still need connectivity.', 'Use local inference and durable exportable storage;Separate collector connectivity from model inference;Keep access control, audit, backups, and restoration procedures;Expose unsupported predictions as unavailable instead of generating a persuasive answer', 'Offline operation|Model governance|Learning decision ledger', 'nist_playbook')
note('11-Underwriting-Intelligence', 'Right censoring', 'An unfinished episode reveals that no terminal outcome was observed through its follow-up time. It is not evidence of a failed transaction.', 'Choose an explicit observation cutoff;Use elapsed time for open episodes;Keep administrative censoring separate from loss to follow-up;Examine whether follow-up loss relates to unobserved outcome risk', 'Competing closing outcomes|Time origin and landmark forecasts|Temporal validation', 'survival_competing')
note('11-Underwriting-Intelligence', 'Cash receipt lag', 'A funded closing and the company receiving cash can occur at different times. Estimate the post-closing collection lag separately from time to closing.', 'Record funded date, received date, and receipt amount;Keep unpaid closed episodes censored for collection analysis;Separate partial and final collections;Show how funding delays affect the cash calendar', 'Working capital|Competing closing outcomes|Settled economics reconciliation', 'survival_competing|cfpb_closing')
note('11-Underwriting-Intelligence', 'Counterfactual seller acceptance', 'An observed accepted offer provides evidence about that price and its terms. It does not establish what the same seller would have done under an unobserved alternative.', 'Preserve all offered prices and terms, including refusals;Record policy and selection effects;Limit predictions to supported price-term regions;Use controlled variation or reviewed causal methods before interpreting a negotiation change as an improvement', 'Seller response evidence|Offer negotiation optimization|Feature selection', 'nist_playbook|sklearn_leakage')
note('11-Underwriting-Intelligence', 'Capacity aware acquisition', 'A profitable-looking contract can be impractical when buyer funding, partner throughput, title work, or staff capacity is already committed elsewhere.', 'Define observable capacity and commitment units;Share demand constraints across competing episodes;Reserve room for uncertainty and delayed exits;Do not assume public buyer activity proves available capacity today', 'Buyer partner liquidity|Portfolio concentration|Working capital', 'occ_cre')
note('11-Underwriting-Intelligence', 'Value of information', 'Additional information has value when it can change a decision enough to justify acquisition cost, time, and delay exposure.', 'List decisions that the missing evidence could change;Evaluate plausible results and resulting actions;Subtract inspection or document cost and holding delay;Distinguish a heuristic priority score from a validated expected information value', 'Intervention queue|Valuation uncertainty|Offer negotiation optimization', 'nist_playbook')
note('11-Underwriting-Intelligence', 'Marginal marketing allocation', 'The return on the next acquisition dollar may differ from a market historical average because channels saturate, costs rise, and operational capacity changes.', 'Keep dated spend and attributable outcomes by mature cohort;Include cancellations and labor costs;Estimate incremental response rather than extrapolating an average;Use capacity and downside constraints before increasing budgets', 'Cash conversion cycle|Capacity aware acquisition|Transaction portfolio economics', 'occ_cre|nist_playbook')
note('11-Underwriting-Intelligence', 'Demand deterioration detection', 'Changes in executable bids, partner approvals, concessions, renegotiations, and closing delays may reveal demand deterioration before completed-sale averages adjust.', 'Monitor matched cohorts and comparable products;Separate source coverage changes from market change;Require adequate recent samples and uncertainty;Record the evidence that triggers repricing or inventory review', 'Buyer partner liquidity|Data freshness|Temporal validation', 'nist_playbook')
note('11-Underwriting-Intelligence', 'Time origin and landmark forecasts', 'A closing forecast needs a defined starting event. Updated stage-specific forecasts condition on surviving and reaching that stage with information available then.', 'Record offer, contract, approval, and funded dates separately;Avoid mixing elapsed contract time with remaining time;Rebuild stage-specific risk sets without future evidence;Display sample support at each forecast horizon', 'Competing closing outcomes|Right censoring|Temporal evidence availability', 'survival_competing')
note('11-Underwriting-Intelligence', 'Probability calibration audit', 'Calibration compares forecast probabilities with observed frequencies over comparable sufficiently observed cases. A rank score is not a calibrated probability.', 'Preserve original horizon predictions;Evaluate mature or appropriately censoring-adjusted outcomes;Show bin counts and uncertainty;Report discrimination and proper scores separately from reliability', 'Model calibration|Competing closing outcomes|Model promotion gate', 'sklearn_calibration')
note('11-Underwriting-Intelligence', 'Temporal evidence availability', 'Information observed later can falsely improve a historical forecast if it is included in the decision-time feature snapshot.', 'Store observed_at and available_at for each fact;Filter evidence using the original prediction timestamp;Fit transformations on the training period only;Retain historical dataset and feature snapshots for replay', 'Temporal validation|Learning decision ledger|Feature selection', 'sklearn_leakage')
note('11-Underwriting-Intelligence', 'Settled economics reconciliation', 'A model target for realized contribution must reconcile retained receipts and attributable expenses across successful and failed episodes.', 'Keep gross spread and partner allocation distinct;Use actual collected amounts and their dates;Include lead spending, transaction costs, and failed-contract loss exposure under a stated policy;Leave missing material costs unresolved instead of substituting zero', 'Realized profit|Transaction portfolio economics|Closing statement reconciliation', 'cfpb_closing')
note('11-Underwriting-Intelligence', 'Model promotion gate', 'Promotion binds a reviewed candidate artifact and reproducible evaluation to an active model version. More records alone do not prove improved performance.', 'Use chronological evaluation after training and calibration periods;Compare relevant errors and reliability with the active baseline;Record approval, scope, evidence, and metrics;Preserve a previous version for rollback and reject unsupported deployment claims', 'Learning decision ledger|Probability calibration audit|Model governance', 'mlflow_registry|sklearn_calibration|sklearn_leakage')


# Public completed transaction records: original factual selection, never invented P&L.
DEALS = []
def deal(sid, name, location, period, price, gain, units=None, *, interest=100.0,
         exact_date=None, kind='asset_sale', value_type='gross_sales_price',
         gain_scope='consolidated_reported', net_proceeds=None, extra='', cost_basis=None):
    did = f'deal-{len(DEALS)+1:04d}'
    DEALS.append(dict(id=did, asset_name=name, seller=SOURCES[sid]['publisher'], location=location,
        closing_date=exact_date, closing_period=period, date_precision='day' if exact_date else ('quarter' if period.startswith('Q') else 'month' if re.match(r'\d{4}-\d{2}$',period) else 'period'),
        transaction_type=kind, interest_sold_pct=interest, unit_count=units,
        disclosed_value_usd=round(price*1000), disclosed_value_type=value_type,
        net_cash_proceeds_usd=net_proceeds, cost_basis_usd=cost_basis,
        reported_gain_usd=round(gain*1000), measurement_type='reported_accounting_disposition_gain',
        gain_scope=gain_scope, realized_cash_profit_usd=None, realized_irr=None,
        source_ids=[sid], source_url=SOURCES[sid]['url'], source_locator=SOURCES[sid]['locator'],
        evidence_status='completed_positive_reported_gain', accessed_utc=ACCESSED,
        limitations='Original purchase price, complete holding-period cash flows, financing costs, taxes and overhead are not disclosed in this selected transaction record. Reported gain is not cash profit or IRR. '+extra))

