def safe_title(title):
    return re.sub(r'[<>:"/\\|?*]', '-', title).strip().replace('  ',' ')

def frontmatter(title, kind, tags, **kwargs):
    pairs = dict(title=title, kind=kind, owner='101XVC', reviewed_utc=ACCESSED, tags=tags, **kwargs)
    return '---\n' + ''.join(f'{k}: {json.dumps(v,ensure_ascii=False)}\n' for k,v in pairs.items()) + '---\n\n'

def write(path, text):
    p = ROOT / path
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text, encoding='utf-8')
    return p

def money(x):
    return 'Not disclosed' if x is None else f'${x:,.0f}'

MANIFEST_NOTES = []
for n in NOTES:
    stem = safe_title(n['title'])
    path = f"{n['folder']}/{stem}.md"
    text = frontmatter(n['title'], 'operational_knowledge', ['real-estate',n['folder'].split('-',1)[1].lower()], source_ids=n['source_ids'], evidence_scope='Original analytical workflow with linked primary domain references')
    text += f"# {n['title']}\n\n{n['concept']}\n\n## 101XVC workflow\n\n" + '\n'.join('- '+a.strip() for a in n['actions'])
    text += '\n\n## Related notes\n\n' + ', '.join(f'[[{safe_title(x)}]]' for x in n['related'])
    text += '\n\n## Primary references\n\n' + '\n'.join(f"- [{SOURCES[s]['title']}]({SOURCES[s]['url']})" for s in n['source_ids'])
    text += '\n\nReference scope: the links support the topic domain. The workflow is original 101XVC analysis, not a quotation, jurisdiction-wide legal conclusion, or agency endorsement. Check the current authoritative requirements for the actual transaction.\n'
    write(path,text)
    MANIFEST_NOTES.append(dict(id='note-'+re.sub('[^a-z0-9]+','-',n['title'].lower()).strip('-'), title=n['title'], path=path, source_ids=n['source_ids'], kind='operational_knowledge'))

for d in DEALS:
    title=f"{d['id']} {d['asset_name']}"
    d['note_path']='09-Closed-Deals/'+safe_title(title)+'.md'
    text=frontmatter(title,'completed_transaction_case',['real-estate','completed-transaction'],deal_id=d['id'],evidence_status=d['evidence_status'],measurement_type=d['measurement_type'],source_ids=d['source_ids'])
    text+=f"# {d['asset_name']}\n\n| Field | Disclosed fact |\n|---|---|\n| Seller | {d['seller']} |\n| Location | {d['location']} |\n| Closed period | {d['closing_period']} |\n| Exact close date | {d['closing_date'] or 'Not disclosed'} |\n| Transaction | {d['transaction_type']} |\n| Interest sold | {str(d['interest_sold_pct'])+'%' if d['interest_sold_pct'] is not None else 'Not disclosed'} |\n| Reported transaction value | {money(d['disclosed_value_usd'])} |\n| Value definition | {d['disclosed_value_type']} |\n| Net cash proceeds | {money(d['net_cash_proceeds_usd'])} |\n| Cost basis | {money(d['cost_basis_usd'])} |\n| Reported disposition gain | {money(d['reported_gain_usd'])} |\n| Gain scope | {d['gain_scope']} |\n| Actual cash profit / IRR | Not established |\n\n"
    text+='## Interpretation\n\n'+d['limitations']+'\n\n'
    text+=f"Evidence is an issuer-reported completed transaction with the reported gain shown above. Positive reported gain alone does not prove a fully net-profitable investment. No purchase price or return is invented.\n\n## Source\n\n[{SOURCES[d['source_ids'][0]]['title']}]({d['source_url']})\n\nLocator: {d['source_locator']}. Accessed {ACCESSED} UTC.\n\nRelated: [[Closed deal evidence]], [[Accounting gain]], [[Realized profit]], [[Deal evidence map]].\n"
    write(d['note_path'],text)

